213	                  {opt.label}
214	                </option>
215	              ))}
216	            </select>
217	          </div>
218	
219	          {/* Message */}
220	          <div className={styles["field"]}>
221	            <label htmlFor="message" className={styles["label"]}>
222	              Message
223	            </label>
224	            <Textarea
225	              id="message"
226	              name="message"
227	              placeholder="Enter your message..."
228	              value={fields.message}
229	              onChange={handleChange}
230	              required
231	              className={styles["textarea"]}
232	            />
233	          </div>
234	
235	          {/* Error */}
236	          {status === "error" && (
237	            <div className={styles["errorMsg"]}>
238	              <AlertCircleIcon />
239	              Oops! Something went wrong. Please try again or email us directly.
240	            </div>
241	          )}
242	
243	          {/* Submit */}
244	          <button
245	            type="submit"
246	            className={styles["submitBtn"]}
247	            disabled={status === "submitting"}
248	          >
249	            {status === "submitting" ? "Please wait..." : "Send Message"}
250	          </button>
251	        </form>
252	      </div>
253	    </section>
254	  );
255	}
